"""Embedded update signing key. Generated by scripts/release/make-update.py --keygen."""

PUBLIC_KEY_N_HEX = ""
PUBLIC_KEY_E = 65537

def get_public_key() -> tuple[int, int] | None:
    if len(PUBLIC_KEY_N_HEX) != 768:
        return None
    try:
        modulus = int(PUBLIC_KEY_N_HEX, 16)
    except ValueError:
        return None
    if modulus.bit_length() != 3072 or PUBLIC_KEY_E != 65537:
        return None
    return modulus, PUBLIC_KEY_E
